// seed: tests/seed.admin.spec.ts (admin, с #359741; было: гость) · прод, только чтение. Источник: F-06 AC 4 «אין autoplay עם קול», D-06.
// Момент «страница загрузилась» — все 5 постеров /guides/<id>.jpg ответили 200; после него запросов mp4 быть не должно.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, GUIDES, LOAD, openGuides, videoOf } from './guides.helpers';

// #359741: /guides видит только админ (гость и user уходят на /) — сессия admin, файл сессии не перезаписывается.
test.use({ storageState: '../auth/admin.json', serviceWorkers: 'block' });

test.describe('Видео-инструкции /guides', () => {
  test('/guides: видео не запускаются сами — preload none, paused, mp4 не грузится без клика #8790d6 @desktop @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    const mp4: string[] = [];
    const posters = new Set<string>();
    page.on('request', (r) => {
      if (/^\/guides\/[^/]+\.mp4$/.test(new URL(r.url()).pathname)) mp4.push(r.url());
    });
    page.on('response', (r) => {
      const m = new URL(r.url()).pathname.match(/^\/guides\/([^/]+)\.jpg$/);
      if (m && r.status() === 200) posters.add(m[1]);
    });

    await openGuides(page);
    await expect
      .poll(() => [...posters].sort(), { message: 'все 5 постеров /guides/<id>.jpg ответили 200', ...LOAD })
      .toEqual(GUIDES.map((g) => g.id).sort());

    for (const g of GUIDES) {
      const s = await videoOf(page, g).evaluate((v: HTMLVideoElement) => ({
        autoplay: v.autoplay, preload: v.getAttribute('preload'), paused: v.paused, readyState: v.readyState,
      }));
      expect(s, `${g.id}: без автозапуска и без предзагрузки`).toEqual({ autoplay: false, preload: 'none', paused: true, readyState: 0 });
    }
    expect(mp4, 'запросов /guides/*.mp4 без нажатия нет').toEqual([]);
  });
});
